<x-admin.page :title="$pageId ? $title : 'Add page'" subtitle="Publish rich storefront content."><x-slot:actions><flux:button wire:click="save" variant="primary" icon="check">Save page</flux:button></x-slot:actions><form wire:submit="save" class="grid gap-6 xl:grid-cols-3"><div class="space-y-6 xl:col-span-2"><x-admin.panel heading="Content"><div class="space-y-4"><flux:input wire:model.live="title" label="Title" /><flux:textarea wire:model="bodyHtml" label="Content" rows="16" /><flux:error name="title" /></div></x-admin.panel><x-admin.panel heading="Search engine listing"><flux:input wire:model="handle" label="URL handle" prefix="/pages/" /><flux:error name="handle" /></x-admin.panel></div><x-admin.panel heading="Publishing" class="h-fit"><flux:select wire:model="status" label="Status"><flux:select.option value="draft">Draft</flux:select.option><flux:select.option value="published">Published</flux:select.option><flux:select.option value="archived">Archived</flux:select.option></flux:select></x-admin.panel><div class="sticky bottom-0 flex justify-end gap-2 border-t border-zinc-200 bg-white/95 p-4 dark:border-zinc-800 dark:bg-zinc-950/95 xl:col-span-3"><flux:button href="/admin/pages" wire:navigate>Discard</flux:button><flux:button type="submit" variant="primary">Save</flux:button></div></form></x-admin.page>
